import{_ as t,o as n,c as o,a2 as a}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Account and sign-in","description":"Signing in, profile, help, and deleting your account.","frontmatter":{"title":"Account and sign-in","description":"Signing in, profile, help, and deleting your account."},"headers":[],"relativePath":"en/erste-schritte/konto-und-anmeldung.md","filePath":"en/erste-schritte/konto-und-anmeldung.md","lastUpdated":1787319236000}'),r={name:"en/erste-schritte/konto-und-anmeldung.md"};function s(i,e,l,c,d,p){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="account-and-sign-in" tabindex="-1">Account and sign-in <a class="header-anchor" href="#account-and-sign-in" aria-label="Permalink to &quot;Account and sign-in&quot;">​</a></h1><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p>Sign-in happens on its own login page:</p><blockquote><p><strong>Welcome!</strong><em>Enter your login details.</em></p></blockquote><p>You enter your <strong>username</strong> and <strong>password</strong> and confirm with <strong>Sign in</strong>.</p><p>If the details are wrong, you&#39;ll see <em>Please check your username and password</em>; if they&#39;re missing entirely: <em>Username is required</em> or <em>Password is required</em>.</p><div class="tip custom-block"><p class="custom-block-title">No account needed for forms</p><p>Anyone who&#39;s just filling out a <a href="/en/formulare/formular-erstellen">form</a> or viewing a <a href="/en/seiten/portal-veroeffentlichen">portal</a> needs <strong>no</strong> ApptiveGrid account — unless access has been explicitly restricted.</p><p>You only need an account once you want to build Grids, Forms, Flows, or Pages yourself.</p></div><h2 id="on-first-launch" tabindex="-1">On first launch <a class="header-anchor" href="#on-first-launch" aria-label="Permalink to &quot;On first launch&quot;">​</a></h2><p>After your first sign-in, ApptiveGrid asks:</p><blockquote><p><em>What will you be using ApptiveGrid for?</em></p></blockquote><p>You can choose <strong>Personal</strong>, <strong>Work</strong>, or <strong>Other</strong>.</p><p>After that, the Space overview greets you — depending on the time of day, with <em>Good morning</em>, <em>Hello</em>, <em>Welcome</em>, or <em>Good evening</em>.</p><h2 id="checking-who-s-signed-in" tabindex="-1">Checking who&#39;s signed in <a class="header-anchor" href="#checking-who-s-signed-in" aria-label="Permalink to &quot;Checking who&#39;s signed in&quot;">​</a></h2><p>On shared devices, someone else may already be signed in. ApptiveGrid flags this:</p><blockquote><p><em>You are signed in as {email}.</em><em>Please only continue if this is your own account.</em></p></blockquote><p>Confirm with <strong>Yes, I am {name} - continue</strong>, or switch with <strong>Use another account</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Same check for forms and pages</p><p><a href="/en/formulare/formular-erstellen">Forms</a> and <a href="/en/seiten/seitenlayout">pages</a> have the setting <em>Confirm correct account</em> or <em>Show account confirmation notice</em>, respectively.</p><p>This is worth using for applications on shared workshop, reception, or training-room computers — otherwise entries get submitted under someone else&#39;s name.</p></div><h2 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h2><p>Under <strong>Profile &amp; settings</strong> → <strong>Profile</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th></th></tr></thead><tbody><tr><td><strong>Profile picture</strong></td><td>Your picture</td></tr><tr><td><strong>First name</strong>, <strong>Last name</strong></td><td>The name shown to others</td></tr><tr><td><strong>Email</strong></td><td>Your address</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Profile pictures have a size limit</p><p><em>Choose an image in jpg format.</em> and <em>The file is too large. Choose an image smaller than 1MB.</em></p></div><p>Your name appears in the <strong>Created by</strong> column and in the <a href="/en/grids/versionsverlauf">version history</a> — visible to other people in the Space.</p><h2 id="account-settings-vs-space-settings" tabindex="-1">Account settings vs. Space settings <a class="header-anchor" href="#account-settings-vs-space-settings" aria-label="Permalink to &quot;Account settings vs. Space settings&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">A common mix-up</p><table tabindex="0"><thead><tr><th>Area</th><th>Applies to</th></tr></thead><tbody><tr><td><strong>Profile &amp; settings</strong></td><td>You personally — profile, billing, API credentials</td></tr><tr><td><strong>Space settings</strong></td><td>One Space — plan, seats, webhooks, links</td></tr></tbody></table><p>The plan is booked per <strong>Space</strong>, but the payment details are tied to the <strong>account</strong>.</p></div><p>→ <a href="/en/spaces/einstellungen">Space settings</a></p><h2 id="billing" tabindex="-1">Billing <a class="header-anchor" href="#billing" aria-label="Permalink to &quot;Billing&quot;">​</a></h2><p>Under <strong>Billing</strong>:</p><blockquote><p><em>Manage subscriptions, download invoices, and update payment or billing details</em></p></blockquote><p>The <strong>Invoices and subscription</strong> button takes you to the payment provider.</p><h2 id="api-credentials" tabindex="-1">API Credentials <a class="header-anchor" href="#api-credentials" aria-label="Permalink to &quot;API Credentials&quot;">​</a></h2><p>Under <strong>API Credentials</strong> you generate keys for accessing the programming interface.</p><div class="danger custom-block"><p class="custom-block-title">Personal and far-reaching</p><blockquote><p><em>Your personal API credentials grant access to all data in your Spaces. Only share these credentials with third-party services and applications you trust.</em></p></blockquote></div><p>→ <a href="/en/integrationen/api-zugangsdaten">API Credentials</a></p><h2 id="help" tabindex="-1">Help <a class="header-anchor" href="#help" aria-label="Permalink to &quot;Help&quot;">​</a></h2><p>Under <strong>Help &amp; Support</strong>:</p><table tabindex="0"><thead><tr><th>Item</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Help Center</strong></td><td>Documentation</td></tr><tr><td><strong>Chat with us</strong></td><td>Direct contact with support</td></tr><tr><td><strong>Send us feedback</strong></td><td>Product feedback</td></tr><tr><td><strong>What&#39;s new?</strong></td><td>Latest updates</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Chat is the fastest route</p><p>For questions this documentation doesn&#39;t answer — like setting up an integration or plan details — chat connects you directly to support.</p></div><p>If a notice about a new app version appears, reload the page.</p><h2 id="preview-features" tabindex="-1">Preview features <a class="header-anchor" href="#preview-features" aria-label="Permalink to &quot;Preview features&quot;">​</a></h2><p>The profile has a toggle labeled <em>Try our latest features</em>.</p><div class="warning custom-block"><p class="custom-block-title">For experimentation only</p><p>This makes features that are still in development visible. They may change or disappear again.</p><p>Don&#39;t rely on them in guides for your team, and leave the toggle off in production use.</p></div><h2 id="deleting-your-account" tabindex="-1">Deleting your account <a class="header-anchor" href="#deleting-your-account" aria-label="Permalink to &quot;Deleting your account&quot;">​</a></h2><p>Under <strong>Profile</strong> → <strong>Delete account</strong>.</p><div class="danger custom-block"><p class="custom-block-title">Permanent</p><blockquote><p><em>Your account and all data will be permanently deleted. Type DELETE into the text field to continue.</em></p></blockquote><p>You must type <code>DELETE</code> to confirm. There&#39;s no way to undo it.</p><p><strong>Check first:</strong> are you the owner of Spaces that others still need? Transfer them beforehand, or back up the data with a <a href="/en/grids/csv-export">CSV export</a>.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/erste-schritte/was-ist-apptivegrid">What is ApptiveGrid</a></li><li><a href="/en/erste-schritte/oberflaeche">The interface at a glance</a></li><li><a href="/en/zusammenarbeit/rollen">Roles</a></li></ul>',46)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
